head.script:
scwin.trigger1_onclick = function(e) {
    dataMap1.setJSON({
        'col1': 'test22'
    });
};
scwin.trigger2_onclick = function(e) {
    input.unbindRef();
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step  1. 샘플 실행 후 "input1.unbindRef()"버튼을 클릭 후 "dataMap1.setJSON()"버튼을 클릭한다.
    //After running the sample, click the "input1.unbindRef ()" button and then the "dataMap1.setJSON ()" button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify  1. 'test'값에 변화가 없다(정상)바인딩이 해제되어 set값이 적용되지 않는다.(이전에는 기능이 없었음)
    //There is no change in the 'test' value (normal)The binding is turned off and the set value is not applied.(Previously no functionality)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input').getValue() == 'test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataMap1.setJSON({
        "col1": "test"
    });
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 25-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
